    {
      "beat": "The trial",
      "narration": "640 adults with chronic insomnia were randomly assigned, in a 1:1 ratio, to a six-week app-delivered CBT programme or to a sleep-hygiene control app.",
      "on_screen": "Title card: 640 adults, chronic insomnia, randomised 1:1; two phone icons labelled CBT app and sleep-hygiene control app; six-week programme.",
      "claim_refs": ["CL01"]
    },
    {
      "beat": "Insomnia scores at week 8",
      "narration": "At week 8, insomnia severity on the Insomnia Severity Index, a 0 to 28 scale where higher is worse, fell 6.8 points in the CBT arm and 3.1 points in the control arm. The between-group difference was 3.7 points, 95% confidence interval 2.9 to 4.5, p < 0.001.",
      "on_screen": "ISI bar chart: CBT -6.8 points, control -3.1 points; caption 'difference 3.7 points (95% CI 2.9 to 4.5), p < 0.001'; scale note '0 to 28, higher scores worse'.",
      "claim_refs": ["CL01"]
    },
    {
      "beat": "The second co-primary endpoint",
      "narration": "But the trial pre-registered two co-primary endpoints and was powered for both. On the second, daytime functioning, scores changed 1.2 points with CBT and 1.0 with control: a difference of 0.2 points, 95% confidence interval -0.7 to 1.1, p = 0.66. That interval includes zero, so the trial establishes neither benefit nor absence of benefit here.",
      "on_screen": "Two endpoint cards side by side, both stamped 'co-primary, 90% power, two-sided alpha 0.025'; WSAS card shows -1.2 vs -1.0, difference 0.2 (95% CI -0.7 to 1.1), p = 0.66, with the interval drawn crossing a zero line.",
      "claim_refs": ["CL02", "CL03"]
    },
    {
      "beat": "Six months later",
      "narration": "At the pre-specified six-month follow-up, the insomnia difference had narrowed to 1.9 points, 95% confidence interval 0.6 to 3.2.",
      "on_screen": "Timeline from week 8 to 6 months; the ISI gap shrinks from 3.7 points to 1.9 points (95% CI 0.6 to 3.2).",
      "claim_refs": ["CL04"]
    },
    {
      "beat": "What to hold in mind",
      "narration": "Every outcome was self-reported, with no actigraphy or polysomnography, and participants could see which app they were using. Attrition was 14% in the CBT arm and 9% in the control arm.",
      "on_screen": "Limitations list: self-reported outcomes only, no actigraphy or polysomnography; participants not blinded to app content; attrition 14% CBT versus 9% control.",
      "claim_refs": ["CL01", "CL02", "CL05"]
    }
  ]
}
